 if(/提交.*后.*流程|申报材料后.*流程/.test(text)){showChat('材料提交后，符合申报要求的方案通常进入路演组织阶段。路演安排、准备要求和后续遴选结果会通过站内通知等渠道发布，请以具体批次通知为准。','依据：场景创新业务问答材料',official.scene,'原型不提供正式路演或遴选状态。');return;}
