 if(/自有数据.*场景|场景.*自有数据/.test(text)){showChat('在合规可控并满足具体实施要求的前提下，场景能力单位可在中心实施时使用自有数据，与获准的公共数据开展融合验证；具体接入方式和安全要求仍需技术与业务核验。','依据：场景创新业务问答材料',official.guide,'原型不处理真实数据接入。');return;}
