function catalogRows(){const f=state.filters;return(state.catalog?.gov||[]).filter(r=>(!f.domain||r.domain_name===f.domain)&&(!f.dept||r.dept_name===f.dept)&&(!f.open||r.is_open==='是')&&(!f.keyword||r.data_name.includes(f.keyword)));}
function renderCatalog(){taskHost.replaceChildren();taskHost.append(E('h2','','数据资源目录'),E('p','hb-muted','政府侧数据 · 2026-09-02公开目录快照'));if(state.load!=='ready'){taskHost.append(E('p','hb-notice',state.load==='error'?'目录加载失败，请重试；不代表没有资源。':'正在读取目录快照…'));if(state.load==='error')taskHost.append(B('重新加载',loadCatalog));return;}
 const metrics=E('div','hb-metrics hb-catalog-metrics');[['政府侧目录',state.catalog.gov.length,'government-line'],['交通运输领域',state.catalog.gov.filter(r=>r.domain_name==='交通运输').length,'bus-line'],['当前筛选结果',catalogRows().length,'file-list-3-line']].forEach(([label,num,icon])=>{const item=E('div');item.append(I(icon),E('span','',label),E('strong','',num.toLocaleString()));metrics.append(item);});taskHost.append(metrics);
 const filters=E('div','hb-filterbar');[['domain','领域',['','交通运输']],['dept','提供部门',['','北京市交通委员会']]].forEach(([key,label,opts])=>{const lab=E('label','',label);const sel=E('select');opts.forEach(v=>{const o=E('option','',v||'全部');o.value=v;o.selected=state.filters[key]===v;sel.append(o);});sel.onchange=()=>{state.filters[key]=sel.value;state.page=1;renderCatalog();};lab.append(sel);filters.append(lab);});const check=E('label','hb-check');const c=E('input');c.type='checkbox';c.checked=state.filters.open;c.onchange=()=>{state.filters.open=c.checked;state.page=1;renderCatalog();};check.append(c,document.createTextNode('仅开放标识“是”'));filters.append(check);const search=E('input');search.placeholder='搜索目录名称';search.setAttribute('aria-label','搜索目录名称');search.value=state.filters.keyword;search.oninput=()=>{state.filters.keyword=search.value;state.page=1;renderResults();};filters.append(search,B('清除条件',()=>{state.filters={domain:'',dept:'',open:false,keyword:''};state.page=1;renderCatalog();},'hb-text-button'));taskHost.append(filters);const host=E('div','hb-catalog-results');taskHost.append(host);renderResults();evidence(taskHost,'数据来源与统计口径',official.catalog,'本地文件：07_政府侧数据.csv，10,659条目录记录。按领域、部门、开放标识精确筛选，不包含底层业务明细。');}
function renderResults(){const host=taskHost.querySelector('.hb-catalog-results');if(!host)return;host.replaceChildren();const rows=catalogRows();const current=taskHost.querySelector('.hb-catalog-metrics>div:last-child strong');if(current)current.textContent=rows.length.toLocaleString();const stat=E('div','hb-stat');stat.append(E('strong','',rows.length.toLocaleString()),E('span','','条目录记录'),E('small','','目录可见 ≠ 数据使用授权'));host.append(stat);const tally={};rows.forEach(r=>tally[r.dept_name]=(tally[r.dept_name]||0)+1);const bars=E('div','hb-bars');Object.entries(tally).sort((a,b)=>b[1]-a[1]).slice(0,3).forEach(([n,count])=>{const b=E('div','hb-bar');b.append(E('span','',n),E('strong','',String(count)));const meter=E('meter');meter.min=0;meter.max=rows.length;meter.value=count;b.append(meter);bars.append(b);});host.append(bars);if(!rows.length)host.append(E('p','hb-empty','当前条件下没有匹配目录，可取消筛选或反馈需求。'));
 rows.slice((state.page-1)*5,state.page*5).forEach(r=>{const card=E('article','hb-resource');const title=E('h3','',r.data_name);const icon=I(/轨道/.test(r.data_name)?'subway-line':/公交|客运/.test(r.data_name)?'bus-line':'database-2-line');icon.classList.add('hb-resource-icon');card.append(icon,title,E('p','hb-muted',r.dept_name+' · '+r.domain_name),E('span','hb-tag',r.is_open==='是'?'开放标识：是':'开放标识：'+(r.is_open||'未提供')));card.append(E('span','hb-tag hb-share-tag','共享标识：'+(r.is_shared||'未提供')));const actions=E('div','hb-actions');actions.append(B(state.compare.includes(r.id)?'已加入比较':'比较',()=>{if(state.compare.includes(r.id))state.compare=state.compare.filter(x=>x!==r.id);else if(state.compare.length<3)state.compare.push(r.id);else{notice('最多比较三项资源。');return;}renderResults();},'hb-text-button'),B('准备需求',()=>begin('demand',r)),B('收藏',()=>{if(!state.favorites.some(x=>x.id===r.id&&x.owner===state.role))state.favorites.push({...r,owner:state.role});notice('已加入本次访问收藏。');},'hb-text-button'));actions.append(L('目录详情 ↗','https://dibj.cn/cxfuww/szzyml/sjml/xqy?id='+encodeURIComponent(r.id)+'&type=DATA&tableCode=GOV_DATA'));card.append(actions);host.append(card);});
 const pages=Math.max(1,Math.ceil(rows.length/5));const pager=E('div','hb-actions');const prev=B('上一页',()=>{state.page--;renderResults();});prev.disabled=state.page<=1;const next=B('下一页',()=>{state.page++;renderResults();});next.disabled=state.page>=pages;pager.append(prev,E('span','',state.page+' / '+pages),next);host.append(pager);if(state.compare.length){const compare=E('section','hb-surface');compare.append(E('h3','','已选资源对比'));state.compare.forEach(id=>{const r=state.catalog.gov.find(r=>r.id===id);compare.append(E('p','',r.data_name+'｜'+r.dept_name+'｜开放：'+r.is_open+'｜共享：'+r.is_shared));});compare.append(B('清空比较',()=>{state.compare=[];renderResults();},'hb-text-button'));host.append(compare);}}
const fifthNotice='https://zwfwj.beijing.gov.cn/zwgk/2024zcwj/202608/t20260803_4806700.html';
const fifthNames=['京智社管','基于数据互联和政企协同的养老综合服务','基于民政养老监管数据的养老金融数字信用评价体系','旅游团队行程智能监测与执法辅助'];
