function renderScenes(){taskHost.replaceChildren();taskHost.append(E('h2','','已发布场景'),E('p','hb-muted','目录阶段分布 · 2026-09-02快照'));if(state.load!=='ready'){taskHost.append(E('p','hb-notice','目录暂未就绪，请稍后重试。'),B('重试',loadCatalog));return;}const stats=E('div','hb-metrics');[['1','揭榜中'],['2','对接中'],['3','已完成']].forEach(([v,l])=>{const item=E('div');item.append(E('strong','',String(state.catalog.scenes.filter(s=>s.scene_range===v).length)),E('span','',l));stats.append(item);});taskHost.append(stats,E('p','hb-notice','阶段不代表当前申请窗口；未核验截止时间前仅准备材料。'));const filter=E('div','hb-filterbar');const sel=E('select');sel.setAttribute('aria-label','场景阶段');[['1','揭榜中'],['2','对接中'],['3','已完成']].forEach(([v,l])=>{const o=E('option','',l);o.value=v;o.selected=state.sceneStage===v;sel.append(o);});sel.onchange=()=>{state.sceneStage=sel.value;state.scenePage=1;renderScenes();};const search=E('input');search.placeholder='搜索场景名称';search.setAttribute('aria-label','搜索场景名称');search.value=state.sceneSearch;search.oninput=()=>{state.sceneSearch=search.value;state.scenePage=1;renderSceneRows();};filter.append(sel,search);taskHost.append(filter,E('div','hb-scene-results'));renderSceneRows();evidence(taskHost,'来源：官网场景目录与历史快照',official.scene,'17_场景需求.csv；目录阶段不代表实时受理状态。正式表单待认证核验。');}
function renderSceneRows(){const host=taskHost.querySelector('.hb-scene-results');host.replaceChildren();const rows=state.catalog.scenes.filter(r=>r.scene_range===state.sceneStage&&r.scene_name.includes(state.sceneSearch)).sort((a,b)=>b.data_time.localeCompare(a.data_time));if(!rows.length)host.append(E('p','hb-empty','未匹配到场景，请调整名称或阶段。'));rows.slice((state.scenePage-1)*5,state.scenePage*5).forEach(r=>{const card=E('article','hb-resource');card.append(E('h3','',r.scene_name),E('p','hb-muted','发布记录日期：'+r.data_time.slice(0,10)));if(isFifth(r))card.append(E('p','hb-notice','第五批通知原截止时间：2026-08-17 17:00。已过原截止时间，是否延期待核验。'),L('查看批次通知 ↗',fifthNotice));const actions=E('div','hb-actions');actions.append(L('查看场景详情 ↗',sceneUrl(r)),B('查看并准备申请',()=>begin('scene',r)));card.append(actions);host.append(card);});const pages=Math.max(1,Math.ceil(rows.length/5));const prev=B('上一页',()=>{state.scenePage--;renderSceneRows();});prev.disabled=state.scenePage<=1;const next=B('下一页',()=>{state.scenePage++;renderSceneRows();});next.disabled=state.scenePage>=pages;const pager=E('div','hb-actions');pager.append(prev,E('span','',state.scenePage+' / '+pages+' · '+rows.length+'条'),next);host.append(pager);}
function renderDiagnosis(){taskHost.replaceChildren();taskHost.append(E('h2','','办理条件核对'),E('p','hb-muted','助手辅助自查 · 未读取官网账号状态'),E('p','hb-notice','资源申请需核对项目团队管理员等条件。企业法人、项目成员和团队管理员承担不同职责，不能相互替代。'));const form=E('div','hb-form');[['company','企业关系',['尚未绑定','已提交绑定，待审核','已完成绑定','不清楚']],['project','项目关系',['尚无项目','已有项目，状态待核对','不清楚']],['team','团队身份',['项目成员','团队管理员','法人或授权人','不清楚']],['network','操作环境',['互联网门户','政务外网','不清楚']]].forEach(([key,label,options])=>{const wrap=E('div','hb-field');const lab=E('label','',label);const sel=E('select');sel.setAttribute('aria-label',label);const empty=E('option','','请选择本人情况');empty.value='';sel.append(empty);options.forEach(v=>{const o=E('option','',v);o.value=v;sel.append(o);});sel.value=state.diagnostic[key]||'';sel.onchange=()=>state.diagnostic[key]=sel.value;wrap.append(lab,sel);form.append(wrap);});taskHost.append(form,B('查看下一步建议',()=>{const v=state.diagnostic;let result='以下建议基于您的自述，实际权限尚未核验。';if(v.company==='尚未绑定'||v.company==='已提交绑定，待审核')result+='请先通过个人中心核对企业绑定与审核情况。';if(v.team==='项目成员'||v.team==='法人或授权人')result+='请确认是否同时具有该项目团队管理员资格；可以请已有授权的管理员继续操作。';if(v.network==='互联网门户')result+='如办理涉及公共数据开发，请按操作说明核对政务外网及可信空间路径。';if(!Object.values(v).some(Boolean))result+='请先选择本人情况，或查看官网个人中心指引。';message(result);},'hb-button primary'),L('查看官网个人中心 ↗',official.center));evidence(taskHost,'依据：客户提供的平台操作问答',official.guide,'项目权限与团队职责依据操作说明；此页是助手自查，不是官网权限管理页。登录失败或姓名缺失需通过原认证渠道核对，不收集密码、验证码和证书。');}
