const field=(key,label,type='text',required=true,options=null)=>({key,label,type,required,options});
function schema(t){if(t.kind==='demand')return[field('company','企业名称'),field('contact','联系人'),field('phone','联系电话','tel'),field('detail','需求详情','textarea')];
 if(t.kind==='visit')return[field('category','申请类别','select',true,['个人预约','社会团体预约']),field('date','参观日期','date'),field('slot','参观场次','select',true,['13:30—14:30','15:00—16:00']),...(t.values.category==='个人预约'?[field('contact','姓名'),field('idcard','身份证号'),field('phone','手机号','tel'),field('people','参观人数','number')]:[field('company','单位名称'),field('people','预计总人数','number'),field('contact','领队姓名'),field('phone','领队手机号','tel')])];
 if(t.kind==='scene')return[field('participation','参与方式','select',false,['单独申报','联合体']),field('outline','能力与材料准备说明','textarea',false)];
 if(t.kind==='project')return[field('outline','创新目标与资源需求摘要','textarea',false),field('relation','企业与项目关系核对','select',false,['待核对','已有企业关系，项目待核对','已有项目，管理员资格待核对'])];
 return[field('name','组件工具名称'),field('classification','组件工具分类','select',true,['人工智能 / 自然语言处理','大数据 / 数据计算与分析','其他分类待核对']),field('provider','组件工具包服务商'),field('version','组件工具版本'),field('architecture','支持架构','select',true,['X86','ARM','X86/ARM']),field('logo','组件工具Logo（PNG）','file'),field('description','组件工具说明','textarea'),field('method','组件工具调用方式','textarea'),field('url','组件工具安装包的下载地址及提取码','textarea'),field('report','质量测试报告（Word或PDF）','file'),field('company','单位名称'),field('credit','统一社会信用代码'),field('address','注册地址'),field('legal','法定代表人'),field('contact','申请联系人姓名'),field('phone','申请联系人电话','tel'),field('position','申请联系人职务'),field('email','申请联系人邮箱/传真')];}
function begin(kind,object=null,text=''){
 const title={demand:'需求反馈',visit:'参观预约',scene:'场景申请准备',project:'数据创新项目准备',component:'提供组件'}[kind];
 const thread=ensureThread();if(thread.title==='新对话')thread.title=title;const task={id:'DRAFT-'+Date.now(),kind,title,owner:state.role,threadId:thread.id,object,values:kind==='visit'?{category:state.role==='enterprise'?'社会团体预约':'个人预约'}:{},origins:{},revision:0,confirmation:null,status:'草稿',created:Date.now(),updated:Date.now(),events:[]};
 state.drafts.push(task);state.task=task;state.view='task';
 if(object&&kind==='demand'){task.values.detail='希望了解“'+object.data_name+'”的获取条件。具体用途与需求范围待补充。';task.origins.detail='关联目录生成的建议 · 待确认';}
 message('已打开'+title+'。左侧填写或修改，右侧可继续提问；两边使用同一份草稿。'+(kind==='scene'||kind==='project'?'正式表单尚未核验，这里仅提供助手准备清单。':'请核对建议内容后再继续。'));render();if(text)patch(text,true);
}
function taskHelp(){const t=state.task;if(t.kind==='demand')return '独立需求反馈页要求企业名称、联系人、联系电话、需求详情四项必填。建议说明使用目的、所需资源和希望获得的支持。反馈不等于数据授权；您的修改不会被自动提交。';if(t.kind==='visit')return '预约分个人与社会团体。团体超过20人需工作人员一对一排期；页面中的场次来自历史资料，实时名额未接入。身份证等敏感信息建议在正式官网安全表单中填写。';if(t.kind==='component')return '组件供给需要核对工具信息、PNG Logo、第三方质量测试报告及单位联系人资料。附件选中只表示本地选择，不代表正式上传或质量合格。';return '先核对所选对象、当前批次、企业或团队身份与申请窗口。当前仅为准备清单，正式字段和操作权限以官网为准。';}
function patch(text,silent=false){const t=state.task;const changes=[];const fields=schema(t);fields.forEach(f=>{if(f.type==='file')return;const aliases={company:'企业名称|单位名称|公司名称|单位',contact:'申请联系人姓名|领队姓名|联系人|姓名',phone:'申请联系人电话|领队手机号|联系电话|手机号|电话',detail:'需求详情|需求描述',people:'预计总人数|参观人数|人数',name:'组件工具名称|组件名称',version:'组件工具版本|版本',outline:'准备说明|创新目标|目标',description:'组件工具说明|组件说明',provider:'组件工具包服务商|提供方'};const names=aliases[f.key]||f.label;const re=new RegExp('(?:'+names+')(?:改为|改成|修改为|是|为|：|:|\\s)+([^；;\\n]+)');const m=text.match(re);if(m){let v=m[1].trim().replace(/，其他不变.*$/,'');if(!['textarea'].includes(f.type))v=v.split(/[，,。]/)[0].trim();if(f.type==='number')v=v.replace(/人.*$/,'');if(f.options&&!f.options.includes(v))return;if(f.type==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(v))return;if(v){t.values[f.key]=v;t.origins[f.key]=text.startsWith('材料内容：')?'辅助材料候选 · 待确认':'本轮对话 · 待确认';changes.push(f.label);}}});
 const people=text.match(/(?:改为|改成|预计|共|有)\s*(\d+)\s*人/);if(people&&fields.some(f=>f.key==='people')){t.values.people=people[1];t.origins.people='本轮对话 · 待确认';changes.push('人数');}
 if(!changes.length)return false;t.revision++;t.updated=Date.now();t.confirmation=null;t.events.push({time:Date.now(),text:'对话更新：'+changes.join('、')});if(!silent||changes.length)message('已更新'+[...new Set(changes)].join('、')+'，其他字段保持不变。请在左侧核对。');renderTask();updateSync();return true;}
function validation(t){const errors={};schema(t).forEach(f=>{const v=String(t.values[f.key]||'').trim();if(f.required&&!v)errors[f.key]='请填写'+f.label;else if(f.type==='tel'&&v&&!/^(1\d{10}|0\d{2,3}-?\d{7,8})$/.test(v))errors[f.key]='请填写11位手机号或带区号的固定电话';else if(f.type==='number'&&v&&(!/^\d+$/.test(v)||+v<1))errors[f.key]='人数应为大于0的整数';else if(f.type==='date'&&v&&v<[new Date().getFullYear(),String(new Date().getMonth()+1).padStart(2,'0'),String(new Date().getDate()).padStart(2,'0')].join('-'))errors[f.key]='请选择今天或之后的日期';else if(['description','method'].includes(f.key)&&v.length>500)errors[f.key]='内容不能超过500字';else if(f.type==='url'&&v&&!/^https?:\/\/[^\s]+$/i.test(v))errors[f.key]='请填写完整的 http 或 https 地址';});return errors;}
function visitRule(t){return +t.values.people>20?'超过20人，需工作人员一对一排期。保存准备信息后请联系官网；不生成预约成功回执。':'实时场次余量未接入，仅保存预约准备信息；时间与名额需在官网确认。';}
